#include <sys/socket.h>
#include <linux/uaccess.h>
#include <unistd.h>
#include <errno.h>

int handle_socket_receive(int fd, void __user *ubuf, size_t size, unsigned int flags,
                          struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret, copied_addr_len = 0;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    if (addr_len) {
        if (get_user(copied_addr_len, addr_len)) {
            ret = -EFAULT;
            goto out;
        }
        msg.msg_namelen = copied_addr_len;
    }

    ret = sock->ops->recvmsg(sock, &msg, size, flags);

    if (addr && addr_len) {
        if (put_user(msg.msg_namelen, addr_len)) {
            ret = -EFAULT;
        }
    }

out:
    sockfd_put(sock);
    return ret;
}

int recv_socket_data(int fd, void __user *ubuf, size_t size, unsigned int flags,
                     struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock = fd_getsock(fd);
    if (!sock)
        return -EBADF;

    struct msghdr msg;
    struct iovect iov;
    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = (addr && addr_len) ? *addr_len : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    int bytes_received = sock->ops->recvmsg(sock, &msg, size, flags);
    if (bytes_received < 0)
        return bytes_received;

    if (addr && addr_len) {
        if (put_user(msg.msg_namelen, addr_len))
            return -EFAULT;
    }

    return bytes_received;
}

#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

int receive_data(int fd, void __user *ubuf, size_t size, unsigned int flags,
                 struct sockaddr __user *addr, int __user *addr_len) {
    struct msghdr msg = {0};
    struct iovecnt iov;
    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_flags = flags;

    struct sock *sk = sockfd_lookup(fd, NULL);
    if (!sk) {
        return -ENOTSOCK;
    }

    int ret = sock_recvmsg(sk, &msg, flags);
    if (ret < 0) {
        return ret;
    }

    if (addr && addr_len) {
        int len = 0;
        struct sockaddr *sa = (struct sockaddr *)addr;
        memcpy(sa, &msg.msg_name, msg.msg_namelen);
        len = msg.msg_namelen;
        if (copy_to_user(addr_len, &len, sizeof(int)) != 0) {
            return -EFAULT;
        }
    }

    return ret;
}

int recv_from_socket(int fd, void __user *ubuf, size_t size, unsigned int flags, struct sockaddr __user *addr, int __user *addr_len) {
    struct msghdr msg;
    struct iovecnt iov;
    int ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(*addr) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    ret = kernel_recvmsg(fd, &msg, flags, size);
    if (ret < 0)
        return ret;

    if (addr && addr_len) {
        int len = 0;
        if (copy_to_user(addr_len, &len, sizeof(len)))
            return -EFAULT;
    }

    return ret;
}

